STAGES = [
('creation','Create','Opportunity creation','Sales · Marketing · BDRs · Partners','Pre-pipeline; direct Stage 1 saves Pipeline','Capture a traceable opportunity and route it to the right starting point.','Source and matching reference; originating Contact; core deal details; SAL at creation.','Inbound enters Validate. Assigned seller-self-qualified opportunities may enter Discovery directly.',['source','conversion','forecast']),
('s0','0','Validate','Marketing · Partners · BDRs · assigned seller','Pre-pipeline','Qualify the handoff and establish seller accountability.','Assigned seller acceptance and all five CHAMPS answers for non-self-qualified inbound intake.','Before Stage 1: assignment, acceptance, originating Contact and inbound CHAMPS.',['sal-review','challenge','authority','money','priority','stack']),
('s1','1','Discovery','Sales · Sales Engineering','Pipeline','Establish business fit and the customer use case.','CHAMPS, use case, route to market, AE/Primary SE and at least one assigned Contact Role.','SQL is recorded on entry. Complete discovery before Stage 2; quoting stays disabled here.',['use-case','route','buying-committee','conversion','challenge','authority','money','priority','stack']),
('s2','2','Solution design','Sales · Sales Engineering','Pipeline','Assess technical fit through candidate configurations.','Pain, competitors, Technical Value, Champion, criteria, Description, technical links and resolved required POC.','Complete Stage 2 evidence and an explicit POC decision before Stage 3.',['pain','competition','technical-value','champion','criteria','deal-context','poc','quoting']),
('s3','3','Buyer alignment','Sales · Sales Engineering','Upside','Agree one configuration and align the buying decision.','Technical Win, selected configuration, Operational Value, Economic Buyer and Decision Process.','Technical Outcome must be Technical Win before Stage 4.',['technical-outcome','technical-value','operational-value','economic-buyer','decision-process']),
('s4','4','Proposal / negotiate','Sales · Sales Engineering','Upside','Align the commercial proposal with business value.','Quantified Business Value, Primary Quote, Paper Process and Requested Install Date.','Complete Stage 4 requirements before Stage 5; confirm logistics applicability for non-shipping motions.',['business-value','quoting','paper-process','logistics','ipg']),
('s5','5','Procurement','Sales · Sales Engineering','Commit','Complete the procurement package and delivery timing.','IPG disposition, secured/attached PO, final agreements, shipping estimate, requested delivery and notes.','Complete procurement evidence before Won decision; quoting revisions remain permitted in Stage 5.',['procurement','ipg','logistics','quoting']),
('s6','6','Won decision','Sales · Sales Engineering; OM and GSS handoff','Commit','Capture why the customer chose us and prepare order and deployment review.','Win evidence and conditional interview/contributor information; reconciled package; coordinating deployment Case.','OM must confirm reconciliation before Stage 7; identify the GSS owner and handoff plan before booking.',['won-decision','interviews','win-wire','booking','deployment','value-realization']),
('s7','7','Closed won','Order Management · GSS','Won','Confirm booking and coordinate fulfillment.','OM-confirmed booked PO, locked Close Date and booked facts; linked Order/Case delivery plan.','Complete verified on-site receipt of in-scope items controls Stage 8; partial delivery remains in Stage 7.',['booking','logistics','invoice','deployment','partner-credit']),
('s8','8','Invoice','Order Management · GSS','Won','Complete the Opportunity at verified on-site delivery.','Complete delivery evidence; invoice references and dates when issued; linked deployment Case.','Final Opportunity stage. Pending invoices, deployment and value assessment continue on Order/Case.',['invoice','deployment','value-realization','time-to-value']),
('lost','Lost','Closed lost','Sales · Sales Engineering','Loss','Capture the decision, learning and appropriate follow-up.','Loss reason/details, competitor outcome, next-step recommendation and conditional interview capture.','Use the loss-entry rules and actual decision date; prior sales gates need not be completed to record a loss.',['loss','competition','interviews']),
('post','Case','Deployment & value','GSS · Order Management','Opportunity remains Won','Deliver the agreed outcome and confirm customer value.','Coordinating Case, workstream evidence, value plan, target date and final outcome assessment.','Continues on the Case after Stage 8; it is not an additional Opportunity stage.',['deployment','value-realization','time-to-value'])
]

# Additional reference terms share the module's role, scope, example and source.
# Each item: term, module, meaning, distinction.
TERMS = [
('MQL — Marketing Qualified Lead','conversion','The Contact qualification milestone supplied by Marketing’s automation platform.','MQL is distinct from AQL; neither is fabricated for a seller-direct SQL.'),
('AQL — Agentic Qualified Lead','conversion','The Contact qualification milestone supplied by PAX.AI.','PAX.AI is the qualification channel, not a newly approved Opportunity Source choice.'),
('SAL — Sales Accepted Lead','sal-review','The conversion milestone recorded when an opportunity is created for its originating Contact and Opportunity Conversion Lifecycle.','In this framework, SAL creation does not itself mean the assigned seller has accepted the handoff.'),
('SQL — Sales Qualified Lead','conversion','The conversion milestone recorded on first entry to Discovery, after the applicable acceptance and qualification checks.','Seller-qualified direct Stage 1 creation records SAL and SQL together without inventing prior MQL/AQL.'),
('Conversion Contact','conversion','The designated originating Contact resolved and associated with the opportunity for conversion tracking.','A conversion Contact is required at creation; the full buying committee develops later.'),
('Opportunity Conversion Lifecycle','conversion','The system-maintained Opportunity milestone showing SAL at creation and SQL at Stage 1, retained after discovery.','It is separate from the numbered sales Stage and the existing Contact/Account lifecycle.'),
('Account Lifecycle Stage (ALS)','conversion','The existing Account lifecycle context whose mappings are extended for approved conversion visibility.','A new Stage 0 opportunity does not downgrade an Account already further through its lifecycle or change customer-state semantics.'),
('Seller-self-qualified entry','sal-review','The assigned seller’s documented direct creation of a qualified opportunity in Stage 1, recording auto-accepted SAL and SQL.','CHAMPS remains required before Stage 2. Integration-created inbound records do not become seller-self-qualified merely because of their creator.'),
('CHAMPS','challenge','The five qualification answers: Challenge, Authority, Money, Priority and Stack / Storage.','All five are due before Stage 1 for non-self-qualified inbound intake, or before Stage 2 for seller-self-qualified entry.'),
('Opportunity Owner / Assigned AE','sal-review','The seller accountable for the opportunity and its relevant acceptance and execution responsibilities.','Current ownership does not rewrite the original sourcing attribution.'),
('Primary SE','use-case','The assigned Sales Engineering lead for technical discovery and solution work, reconciled with the opportunity team.','AE and SE responsibilities are related but their next-action reviews are tracked separately.'),
('Opportunity Type','source','The classification of the sales motion: New Business, Existing Business, Renewal, Internal Transfer or Non-Revenue.','Conditional rules may depend on Type; non-shipping and other motion-specific logistics require confirmed applicability.'),
('Opportunity Name','source','The name identifying the deal clearly at creation.','A name identifies the record; Description later captures substantive customer and solution context.'),
('Amount','quoting','The opportunity’s value, captured at creation and kept current as quoting develops; the Primary CPQ Quote synchronizes quoted Amount.','A manually typed estimate is not an independently reconciled booked amount.'),
('Sourcing User','source','The User credited with originating a Direct or BDR opportunity.','For BDR origin, use the originating BDR rather than the current AE or background integration user.'),
('Sourcing Campaign','source','The existing campaign reference credited with a Marketing-origin opportunity.','The future MAP Marketing Source change is a separate dependency, not a current rename.'),
('Sourcing Partner','source','The verified originating partner Account for Opportunity Source = Partner. Registration and origination are separate.','The sourcing partner may differ from the transacting partner or a later contributor.'),
('Indirect Route Type','route','The required subtype when Route to Market is Indirect.','It is inactive for current attribution when the route is Direct; retain historical selections in audit history.'),
('Additional Use Case Information','use-case','The supporting explanation of the customer workload, context and intended outcome behind the selected Use Case.','It supplies specific context that a broad picklist label cannot convey.'),
('Opportunity Contact Roles','buying-committee','The associations between Salesforce Contacts and their supported buying roles on the opportunity.','At least one assigned role is required before Stage 2; it is separate from the resolved originating Contact check at creation.'),
('Technical Win','technical-outcome','The SE-confirmed Technical Outcome required before Stage 4, supported by the selected configuration and technical evidence.','A completed POC, a populated text field or customer enthusiasm alone does not establish Technical Win.'),
('Technical Loss','technical-outcome','The Technical Outcome indicating a loss in technical evaluation.','It does not pass the Stage 3 → 4 gate and is distinct from the overall Closed lost decision.'),
('Description','deal-context','The concise opportunity narrative covering customer context, intended solution and business need, required in Stage 2.','The Description complements the technical evidence rather than replacing it.'),
('SharePoint Link','deal-context','The existing rich-text location for technical-document links supporting the opportunity.','It can hold multiple references and is not simply a single URL input.'),
('Primary Quote','quoting','The one primary CPQ quote belonging to the opportunity, selected by Stage 4 and synchronizing Amount and Products.','Other quote versions may exist, but they do not all act as the primary commercial record.'),
('Quote Purpose','quoting','The purpose of the CPQ request: Budgetary or Best and Final.','Purpose is separate from Timing Urgency.'),
('Timing Urgency','quoting','The CPQ timing classification, Standard by default or Urgent with an Urgency Reason.','Urgency does not change the quote purpose or bypass the stage restrictions on quoting.'),
('Close Date','next-steps','The expected close date while open, confirmed as the decision date at closure and locked at Closed won.','Do not substitute a later invoice, deployment or value-achievement date for the booked Close Date.'),
('Next Step','next-steps','A dated customer-facing action maintained with expected Close Date in open Stages 1–6.','“Follow up” without a specific action and date does not give the team a useful commitment.'),
('SE Next Step','next-steps','The Sales Engineering technical next action, reviewed separately from the AE’s customer/commercial next step.','An AE review does not automatically stand in for the SE review.'),
('Weekly review freshness','next-steps','Evidence that the AE reviewed Next Step and expected Close Date, and that the SE separately reviewed its technical action.','Unrelated edits do not reset freshness; unchanged values can still be explicitly reviewed.'),
('POC Required?','poc','The explicit Yes/No decision about whether a proof of concept is required before Stage 3.','If Yes, status must be Cancelled or Completed before progressing beyond Stage 2.'),
('POC Status','poc','The tracked POC state; a required POC must reach Cancelled or Completed to pass the Stage 3 entry check.','None, Planning, In Progress and Blocked do not pass. Completed does not automatically mean Technical Win.'),
('Technical Deal Risk Category','risk','The category or categories of the technical risk: Parts, Software, System, Expertise, Timeline, Integration, Migration, Engineering or Support.','Category names the kind of threat; risk level expresses its severity or resolution.'),
('Technical Level of Risk','risk','The supported severity/resolution classification: High, Medium, Low or Resolved.','Resolution should be backed by evidence, not merely by a request being submitted.'),
('Association Engagement Status','partner-accounts','The Active/Inactive state of an associated account’s engagement in the opportunity.','This is not the separate NVIDIA Engagement Status.'),
('NVIDIA Engagement Status','nvidia','The specific Opportunity-level NVIDIA status required when the canonical NVIDIA association is active.','The exact existing mapping and allowed choices remain unverified; do not substitute association Active/Inactive.'),
('Partner-only','partner-credit','Contribution classification for an opportunity created and owned solely by the partner/channel.','Later ownership transfers do not rewrite that origin.'),
('Partner-Led','partner-credit','For non-Partner-only opportunities, classification based on the earliest qualifying partner event before Stage 3.','Preserve the original event even if the opportunity regresses or a partner is later removed.'),
('Joint','partner-credit','For non-Partner-only opportunities, classification when the first qualifying partner event occurs in Stages 3–6.','An association added only after booking does not change frozen automated credit.'),
('Partner contribution override','partner-credit','A management correction to reporting with an audited reason; a blank override uses automated contribution.','Routine association changes or ownership transfers are not management overrides.'),
('Requested Install Date','logistics','The customer’s requested installation date captured in Stage 4 before Stage 5.','It is not actual installation completion or the requested delivery date.'),
('Estimated Shipping Date','logistics','The shipping estimate captured during Stage 5 procurement.','Shipping is distinct from on-site receipt and installation.'),
('Requested Delivery Date','logistics','The desired customer delivery date captured during Stage 5 procurement.','A requested date does not prove actual receipt.'),
('Delivery Notes','logistics','The context needed for order, shipping, receiving and deployment coordination.','Notes should explain dependencies and arrangements rather than replace separate milestone dates.'),
('IPG Finalized','ipg','The disposition Completed or explicitly applicable Not Required, required before Stage 6.','A blank field does not mean Not Required.'),
('PO Secured / PO Attachment','procurement','Confirmation of the secured purchase order and its supporting document, using Salesforce Files for the PO.','A received PO must still be reconciled with the quote and order package.'),
('Final Agreements Received','procurement','Confirmation that the final agreements needed for the procurement package have been received before Stage 6.','A verbal selection or unfinished legal review is not the final agreement package.'),
('Order Review Status','booking','The existing order-processing status used within OM’s reconciliation and booking controls.','A nonblank value is insufficient; allowed and blocked existing states and exception authority require approved mapping.'),
('Sales Order Reference','booking','The link or reference connecting the booked opportunity to its sales order and fulfillment context.','The Order carries continued fulfillment and invoice reconciliation after Opportunity completion.'),
('Won Reason','won-decision','The specific reason the customer selected the solution, captured on entry to Stage 6.','Business Value supplies the detailed win and economic evidence; a reason selection alone is not the whole story.'),
('Incumbent Vendor(s)','competition','The vendors the customer currently uses, or Not Applicable if there are none.','Current use differs from active competitors and the final Competitor Lost To outcome.'),
('Resources Engaged','win-wire','The internal account-team and cross-functional contributors named for wins at amounts ≥$1M.','This inclusive threshold differs from the above-$1M manager Win wire rule.'),
('Deal Team Win Report','win-wire','The additional win report required above $2M.','It supplements the manager-reviewed Win wire required above $1M.'),
('OK to Interview (Win/Loss)?','interviews','The Yes/No decision on whether the Win/Loss team may approach a customer Contact for feedback.','For New Business, Existing Business and Renewal, Yes needs the Contact; No needs the cannot-approach reason.'),
('Contact for Win/Loss Interview','interviews','The Salesforce Contact selected when interview eligibility is Yes.','A free-text name does not substitute for the Contact relationship.'),
('WL Reason Cannot Approach','interviews','The explanatory reason required only when interview eligibility is No.','It should not be required or validated as a hidden field when eligibility is Yes.'),
('Loss Reason','loss','The specific reason for the loss, required at Closed lost with evidence-based details.','There is no Other reason choice; Opportunity Misqualified applies only when the prior stage was 0.'),
('Loss Reason Details','loss','The evidence-based explanation of the decision, competitive factors, gaps, lessons and action.','Distinguish customer-confirmed facts from internal interpretation.'),
('Competitor Lost To','competition','The actual competitive outcome at loss, including the permitted Not lost to competitor choice.','It is different from the incumbent list or all alternatives considered earlier.'),
('Competitor Detail (if Other)','competition','The company name required whenever Other is selected in Competitors or Competitor Lost To.','Use it for the company name, not a replacement for the loss explanation.'),
('Lost — Next Step Recommendation','loss','The appropriate follow-up recommended after the lost decision.','It captures a considered next action or disposition rather than leaving the team to infer what happens next.'),
('Deal Team Loss Report','loss','The restricted report due within two business days for a qualifying loss.','Qualifies at prior Stage ≥3 and amount >$1M, or prior Stage ≥2 and amount >$5M. Never post it to #win-wire.'),
('Invoice Reference / Invoice Date','invoice','Evidence recorded and reconciled when the financial invoice is issued.','Pending issuance does not prevent Stage 8 after full on-site delivery; financial Invoice Date is not the value-tracking baseline.'),
('Deployment Case Link','deployment','The connection to the coordinating PS deployment Case initiated at Stage 6, using confirmed existing Opportunity and Order relationships.','Avoid duplicate Cases on re-entry; deployment and value detail remain on the Case.'),
('Value Realization Plan','value-realization','The Case-based plan for validating the sales-defined operational and business outcomes, begun from Stage 6.','Case Scope of Work alone is not the value-validation plan.'),
('Target Value Realization Date','value-realization','The planned date for confirming customer value, maintained on the coordinating Case.','It is separate from delivery, installation and the final assessment date.'),
('Value Achieved?','value-realization','The final Case assessment: Yes for achieved and confirmed, No for assessed and not achieved, blank while pending.','No does not mean unmeasured; it requires the gap and agreed disposition.'),
('Value Realization Context','value-realization','The measured results, customer confirmation and evidence, or gap and disposition, supporting the Case value assessment.','Case closure alone does not supply this evidence.'),
('Value Outcome Confirmed Date','value-realization','The date of the final Yes/No value assessment on the Case.','It differs from deployment completion and Case closure.'),
('Value Tracking Start Date','time-to-value','The first verified Stage 8/on-site-delivery milestone preserved once on the coordinating Case.','Case creation, booking, invoice date, retries and reassignment do not replace or reset the start.'),
('Pre-pipeline','forecast','The sales forecast category for creation/Stage 0.','A seller-qualified opportunity saved directly in Stage 1 is Pipeline immediately.'),
('Pipeline','forecast','The sales forecast category for Stages 1–2.','It is derived from the permitted stage rather than independently maintained by the seller.'),
('Upside','forecast','The sales forecast category for Stages 3–4.','It does not replace the required technical and buyer-alignment evidence.'),
('Commit','forecast','The sales forecast category for Stages 5–6.','Won decision remains Commit until OM confirms booking.'),
('Won','forecast','The sales forecast category for Stages 7–8.','Deployment and value assessment continue without changing the original booked win.'),
('Loss','forecast','The sales forecast category for Closed lost.','An unrealized post-sales outcome does not convert a booked sale into a loss.'),
('Administrative outcomes','forecast','The existing Duplicate, Transacted-Internal Order and Transacted-Reference Opty dispositions retained with their current handling.','They are not additional sales stages or Closed lost outcomes.'),
]

